ALTER TABLE public.fs_sites ADD COLUMN location_required boolean NOT NULL DEFAULT false, ADD COLUMN latitude double precision, ADD COLUMN longitude double precision, ADD COLUMN radius_m integer NOT NULL DEFAULT 150 CHECK(radius_m BETWEEN 50 AND 2000);
ALTER TABLE public.fs_sites ADD CONSTRAINT fs_site_coordinates CHECK((latitude IS NULL OR latitude BETWEEN -90 AND 90) AND (longitude IS NULL OR longitude BETWEEN -180 AND 180) AND (NOT location_required OR (latitude IS NOT NULL AND longitude IS NOT NULL)));
CREATE FUNCTION public.fs_distance(lat1 double precision,lon1 double precision,lat2 double precision,lon2 double precision) RETURNS double precision LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT 6371000*2*asin(sqrt(least(1::double precision,power(sin(radians(lat2-lat1)/2),2)+cos(radians(lat1))*cos(radians(lat2))*power(sin(radians(lon2-lon1)/2),2)))) $$;
REVOKE ALL ON FUNCTION public.fs_distance(double precision,double precision,double precision,double precision) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fs_distance(double precision,double precision,double precision,double precision) TO authenticated,service_role;
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.fs_command(text,jsonb)'::regprocedure) INTO definition;
 definition:=replace(definition,'IF p_action=''qr'' THEN','IF p_action=''location_settings'' THEN IF m.role<>''supervisor'' THEN RAISE EXCEPTION ''Supervisor permission required''; END IF; UPDATE fs_sites SET location_required=(p_data->>''required'')::boolean, latitude=(p_data->>''latitude'')::double precision, longitude=(p_data->>''longitude'')::double precision, radius_m=(p_data->>''radius'')::integer WHERE id=st.id; PERFORM fs_event(st.id,st.id,''Location verification settings updated'',jsonb_build_object(''required'',p_data->''required'',''radius'',p_data->''radius'')); RETURN ''{}''; ELSIF p_action=''qr'' THEN');
 definition:=replace(definition,'ELSIF p_action IN (''check_in'',''check_out'') THEN','ELSIF p_action IN (''check_in'',''check_out'') THEN IF st.location_required THEN IF p_data->''location'' IS NULL OR coalesce((p_data->''location''->>''latitude'')::double precision,999) NOT BETWEEN -90 AND 90 OR coalesce((p_data->''location''->>''longitude'')::double precision,999) NOT BETWEEN -180 AND 180 OR coalesce((p_data->''location''->>''accuracy'')::double precision,999999) NOT BETWEEN 0 AND st.radius_m OR abs(extract(epoch from now())*1000-coalesce((p_data->''location''->>''timestamp'')::double precision,0))>120000 THEN RAISE EXCEPTION ''Allow a fresh, accurate location reading at the worksite''; END IF; IF fs_distance(st.latitude,st.longitude,(p_data->''location''->>''latitude'')::double precision,(p_data->''location''->>''longitude'')::double precision)>st.radius_m THEN RAISE EXCEPTION ''You are outside the worksite attendance radius''; END IF; END IF;');
 definition:=replace(definition,'PERFORM fs_event(st.id,sh.id,CASE WHEN p_action=''check_in'' THEN ''Checked in'' ELSE ''Checked out'' END);','PERFORM fs_event(st.id,sh.id,CASE WHEN p_action=''check_in'' THEN ''Checked in'' ELSE ''Checked out'' END,jsonb_build_object(''location_verified'',st.location_required,''distance_m'',CASE WHEN st.location_required THEN round(fs_distance(st.latitude,st.longitude,(p_data->''location''->>''latitude'')::double precision,(p_data->''location''->>''longitude'')::double precision)) ELSE NULL END));');
 EXECUTE definition;
END $$;